#include "frame_item.h"
#include <QKeyEvent>
#include <QQuickWindow>
#include <QSGSimpleTextureNode>
#include <QSGTexture>
#include <QWheelEvent>
#include <iterator>
namespace {constexpr qreal zoomSteps[]={0.25,0.33,0.5,0.67,0.75,0.9,1.0,1.25,1.5,2.0,3.0,4.0};}
namespace {struct TextureNode final:QSGSimpleTextureNode{QSGTexture* owned=nullptr;~TextureNode()override{delete owned;}void replace(QSGTexture* texture){delete owned;owned=texture;setTexture(texture);}};}
FrameItem::FrameItem(QQuickItem* parent):QQuickItem(parent){setFlag(ItemHasContents,true);setAcceptedMouseButtons(Qt::AllButtons);setAcceptHoverEvents(true);setActiveFocusOnTab(true);connect(&m_timer,&QTimer::timeout,this,&FrameItem::poll);m_timer.start(8);m_fps.start();}
void FrameItem::setEngine(EngineBridge* value){if(m_engine!=value){m_engine=value;emit engineChanged();}}
void FrameItem::setDiagnosticFrame(const QImage& image){m_image=image;m_generation++;update();}
void FrameItem::setSessionKey(const QString& value){if(m_key!=value){if(m_control)input(QStringLiteral("input_reset"),{});m_key=value;m_generation=m_painted=0;m_image={};update();emit sessionKeyChanged();}}
void FrameItem::setControlEnabled(bool value){if(m_control!=value){if(!value)input(QStringLiteral("input_reset"),{});m_control=value;emit controlEnabledChanged();}}
void FrameItem::poll(){flushPointer();if(!m_engine||m_key.isEmpty()||!isVisible())return;if(m_fps.elapsed()>=1000){m_engine->command({{QStringLiteral("type"),QStringLiteral("render_metrics")},{QStringLiteral("key"),m_key},{QStringLiteral("fps"),m_rendered.exchange(0)*1000.0/m_fps.elapsed()}});m_fps.restart();}NativeFrameView view{};const auto key=m_key.toUtf8();if(!od_frame_acquire(m_engine->native(),key.constData(),&view))return;if(view.generation==m_generation){od_frame_release(view.owner);return;}m_generation=view.generation;m_image=QImage(view.data,int(view.width),int(view.height),int(view.width*4),QImage::Format_ARGB32,od_frame_release,view.owner);if(m_image.size()!=m_frameSize){m_frameSize=m_image.size();clampView();emit viewChanged();}update();}
QRectF FrameItem::imageRect()const{if(m_image.isNull())return {};if(m_zoom<=0){const auto size=m_image.size().scaled(QSize(int(width()),int(height())),Qt::KeepAspectRatio);return QRectF((width()-size.width())/2,(height()-size.height())/2,size.width(),size.height());}const auto size=zoomedSize();return QRectF(size.width()<=width()?(width()-size.width())/2:-m_viewX*size.width(),size.height()<=height()?(height()-size.height())/2:-m_viewY*size.height(),size.width(),size.height());}
qreal FrameItem::fitScale()const{if(m_image.isNull()||width()<=0||height()<=0)return 1;const qreal ratio=window()?window()->effectiveDevicePixelRatio():1;return qMin(width()/m_image.width(),height()/m_image.height())*ratio;}
QSizeF FrameItem::zoomedSize()const{const qreal ratio=window()?window()->effectiveDevicePixelRatio():1;return QSizeF(m_image.width()*m_zoom/ratio,m_image.height()*m_zoom/ratio);}
qreal FrameItem::zoomLevel()const{return m_zoom>0?m_zoom:fitScale();}
qreal FrameItem::viewWidth()const{return m_zoom<=0||m_image.isNull()?1:qMin(1.0,width()/zoomedSize().width());}
qreal FrameItem::viewHeight()const{return m_zoom<=0||m_image.isNull()?1:qMin(1.0,height()/zoomedSize().height());}
void FrameItem::clampView(){m_viewX=qBound(0.0,m_viewX,1-viewWidth());m_viewY=qBound(0.0,m_viewY,1-viewHeight());}
void FrameItem::setViewX(qreal value){m_viewX=value;clampView();update();emit viewChanged();}
void FrameItem::setViewY(qreal value){m_viewY=value;clampView();update();emit viewChanged();}
void FrameItem::setZoom(qreal value){zoomAround(value,QPointF(width()/2,height()/2));}
// Keeps the remote point under the anchor in place while the zoom changes.
void FrameItem::zoomAround(qreal value,QPointF anchor){const auto before=imageRect();const QPointF at=before.isEmpty()?QPointF(0.5,0.5):QPointF((anchor.x()-before.x())/before.width(),(anchor.y()-before.y())/before.height());m_zoom=value<=0?0:qBound(zoomSteps[0],value,zoomSteps[std::size(zoomSteps)-1]);if(m_zoom>0&&!m_image.isNull()){const auto size=zoomedSize();m_viewX=(at.x()*size.width()-anchor.x())/size.width();m_viewY=(at.y()*size.height()-anchor.y())/size.height();}clampView();update();emit viewChanged();}
void FrameItem::zoomStep(bool in,QPointF anchor){const qreal now=zoomLevel(),fit=fitScale();qreal next=now;if(in){for(const qreal step:zoomSteps)if(step>now*1.01){next=step;break;}}else{for(auto step=std::rbegin(zoomSteps);step!=std::rend(zoomSteps);++step)if(*step<now*0.99){next=*step;break;}if(now>fit*1.001&&next<=fit*1.001)next=0;}if(next!=now)zoomAround(next,anchor);}
void FrameItem::zoomIn(){zoomStep(true,QPointF(width()/2,height()/2));}
void FrameItem::zoomOut(){zoomStep(false,QPointF(width()/2,height()/2));}
void FrameItem::geometryChange(const QRectF& next,const QRectF& previous){QQuickItem::geometryChange(next,previous);clampView();update();emit viewChanged();}
QSGNode* FrameItem::updatePaintNode(QSGNode* old,UpdatePaintNodeData*){if(m_image.isNull()||!window()){delete old;return nullptr;}auto* node=static_cast<TextureNode*>(old);if(!node)node=new TextureNode;if(m_painted!=m_generation||!node->owned){node->replace(window()->createTextureFromImage(m_image));node->setFiltering(QSGTexture::Linear);m_painted=m_generation;m_rendered.fetch_add(1);}node->setRect(imageRect());return node;}
void FrameItem::flushPointer(){if(!m_pendingMove.isEmpty()){auto move=m_pendingMove;m_pendingMove.clear();input(QStringLiteral("mouse_move_flush"),move);}}
void FrameItem::input(const QString& type,QVariantMap payload){if(type==QStringLiteral("mouse_move")){m_pendingMove=payload;return;}flushPointer();if(!m_engine||m_key.isEmpty())return;payload.insert(QStringLiteral("type"),type==QStringLiteral("mouse_move_flush")?QStringLiteral("mouse_move"):type);m_engine->command({{QStringLiteral("type"),QStringLiteral("input")},{QStringLiteral("key"),m_key},{QStringLiteral("payload"),payload}});}
void FrameItem::pointer(QMouseEvent* event,const QString& type){if(!m_control)return;const auto rect=imageRect();if(rect.isEmpty()||(!rect.contains(event->position())&&type!=QStringLiteral("mouse_up")))return;m_pointer=event->position();emit pointerChanged();const int button=event->button()==Qt::MiddleButton?1:event->button()==Qt::RightButton?2:0;input(type,{{QStringLiteral("x"),qBound(0.0,(event->position().x()-rect.x())/rect.width(),1.0)},{QStringLiteral("y"),qBound(0.0,(event->position().y()-rect.y())/rect.height(),1.0)},{QStringLiteral("button"),button}});event->accept();}
void FrameItem::mouseMoveEvent(QMouseEvent* event){pointer(event,QStringLiteral("mouse_move"));}
void FrameItem::hoverMoveEvent(QHoverEvent* event){if(!m_control)return;m_pointer=event->position();emit pointerChanged();const auto rect=imageRect();if(!rect.isEmpty()&&rect.contains(event->position()))input(QStringLiteral("mouse_move"),{{QStringLiteral("x"),(event->position().x()-rect.x())/rect.width()},{QStringLiteral("y"),(event->position().y()-rect.y())/rect.height()}});}
void FrameItem::mousePressEvent(QMouseEvent* event){forceActiveFocus();pointer(event,QStringLiteral("mouse_down"));}
void FrameItem::mouseReleaseEvent(QMouseEvent* event){pointer(event,QStringLiteral("mouse_up"));}
void FrameItem::wheelEvent(QWheelEvent* event){if(event->modifiers()&Qt::ControlModifier){if(event->angleDelta().y())zoomStep(event->angleDelta().y()>0,event->position());event->accept();return;}if(!m_control&&m_zoom>0&&!m_image.isNull()){const auto size=zoomedSize();const qreal down=-event->angleDelta().y()/120.0*80,side=-event->angleDelta().x()/120.0*80;if(event->modifiers()&Qt::ShiftModifier)m_viewX+=down/size.width();else{m_viewY+=down/size.height();m_viewX+=side/size.width();}clampView();update();emit viewChanged();event->accept();return;}if(m_control){QMouseEvent move(QEvent::MouseMove,event->position(),event->globalPosition(),Qt::NoButton,Qt::NoButton,event->modifiers());pointer(&move,QStringLiteral("mouse_move"));input(QStringLiteral("mouse_scroll"),{{QStringLiteral("delta_y"),-event->angleDelta().y()/120.0},{QStringLiteral("delta_x"),event->angleDelta().x()/120.0}});event->accept();}}
void FrameItem::keyPressEvent(QKeyEvent* event){if(m_control){input(QStringLiteral("key_down"),{{QStringLiteral("vk"),event->nativeVirtualKey()},{QStringLiteral("key"),event->text()}});event->accept();}}
void FrameItem::keyReleaseEvent(QKeyEvent* event){if(m_control&&!event->isAutoRepeat()){input(QStringLiteral("key_up"),{{QStringLiteral("vk"),event->nativeVirtualKey()},{QStringLiteral("key"),event->text()}});event->accept();}}
void FrameItem::focusOutEvent(QFocusEvent* event){input(QStringLiteral("input_reset"),{});QQuickItem::focusOutEvent(event);}
